step.command:
cat > $WORK/repro-struct-copy.c <<'EOF'
struct S8 { long a,b,c,d,e,f,g,h; };
struct S8 arr[4];
void swap(int i) {
  struct S8 tmp = arr[0];
  arr[0] = arr[i];
  arr[i] = tmp;
}
EOF
echo "Real repro, a minimal ten-line isolation of the bug, see mescc.scm's init-local for the fix applied next step."

cat > $WORK/trivial_call.c <<'EOF'
int helper(int x) { return x + 1; }
int main(void) { return helper(41); }
EOF
$WORK/tcc-boot0-build/tcc-boot0 -c $WORK/trivial_call.c -o $WORK/trivial_call.o && $WORK/tcc-boot0-build/tcc-boot0 $WORK/trivial_call.o -o $WORK/trivial_call && readelf -r $WORK/trivial_call.o | grep PLT32

cat > $WORK/exit_repro.c <<'EOF'
int main(void) { return 7; }
EOF
$WORK/tcc027/tcc27d $WORK/exit_repro.c -o $WORK/exit_repro && $WORK/exit_repro; echo "return 7: exit=$? (correct)"
cat > $WORK/exit_repro2.c <<'EOF'
#include <stdlib.h>
int main(void) { exit(7); }
EOF
$WORK/tcc027/tcc27d $WORK/exit_repro2.c -o $WORK/exit_repro2 && $WORK/exit_repro2; echo "exit(7): exit=$? (wrong, pre-fix: 60)"

diff -u $DISTFILES/../simple-patches/kernel-stat-h.before $DISTFILES/../simple-patches/kernel-stat-h.after && ../bin/simple-patch $WORK/mes-libc/include/linux/x86_64/kernel-stat.h $DISTFILES/../simple-patches/kernel-stat-h.before $DISTFILES/../simple-patches/kernel-stat-h.after && cat > $WORK/stattest.c <<'EOF'
#include <sys/stat.h>
#include <stdio.h>
int main(void){ struct stat st; stat("/etc/hostname", &st); printf("size=%d mtime=%d\n", (int)sizeof(st), (int)st.st_mtime); return 0; }
EOF
$WORK/tcc027/tcc27d $WORK/stattest.c -o $WORK/stattest && $WORK/stattest; echo "expect: size=144"

bash $DISTFILES/../build-scripts/run_hidden_headers.sh bash $DISTFILES/../build-scripts/build_gcc464_cxx.sh mb2 && echo '#include <vector>
#include <iostream>
int main(){ std::vector<int> v{1,2,3}; for(auto x: v) std::cout << x; return 0; }' > $WORK/cxxtest.cc && $WORK/g46/mb2/out/bin/g++ -static $WORK/cxxtest.cc -o $WORK/cxxtest && $WORK/cxxtest

mkdir -p $WORK/stdarg-probe && cd $WORK/stdarg-probe && export PATH=$WORK/cross-toolchain/out14/bin:$WORK/cross-toolchain/out/bin:$PATH && cat > sv.c <<'EOF'
typedef char *mva;
#define mva_start(ap, last) (void)((ap) = (char*)(&(last)) + sizeof (void*))
#define mva_arg(ap, type) (type)(((long*)((ap) = ((ap) + sizeof (void*))))[-1])
__attribute__((noinline)) int stdarg1 (long *one, ...) { mva ap; char c; mva_start (ap, one); c = mva_arg (ap, int); return c; }
int main(void){ char c='m'; return stdarg1((long*)-1, c) != c; }
EOF
for o in -O0 -O1 -O2; do i686-guix-linux-gnu-gcc $o -w sv.c -o sv && ./sv; echo "sv $o rc=$?"; done

cd $WORK/stdarg-probe && export PATH=$WORK/cross-toolchain/out14/bin:$PATH && cat > _start.c <<'EOF'
__attribute__((noinline)) void show(void) { __asm__ volatile("movl %ebp, %eax"); }
int main(void){ show(); return 0; }
EOF
for o in -O0 -O1 -O2; do i686-guix-linux-gnu-gcc $o -S -w _start.c -o _start.$o.s; echo "=== $o ==="; grep -A2 "^show:" _start.$o.s | head -3; done

mkdir -p $WORK/gcc-toolchain && cat > $WORK/gcc-toolchain/union_build.py <<'PYEOF'
import os, sys, filecmp
def real_is_dir(p):
    try: return os.path.isdir(p)
    except OSError: return False
def same_content(a, b):
    try: return os.path.samefile(a, b) or (os.path.isfile(a) and os.path.isfile(b) and filecmp.cmp(a, b, shallow=False))
    except OSError: return False
def union(output, inputs):
    if len(inputs) == 1: os.symlink(inputs[0], output); return
    dirs = [i for i in inputs if real_is_dir(i)]; files = [i for i in inputs if not real_is_dir(i)]
    if dirs and not files: union_of_directories(output, dirs)
    elif files and not dirs:
        if all(same_content(files[0], f) for f in files[1:]): os.symlink(files[0], output)
        else: print("warning: collision, choosing", files[0], file=sys.stderr); os.symlink(files[0], output)
    else: print("warning: file/dir collision, choosing", inputs[0], file=sys.stderr); os.symlink(inputs[0], output)
def union_of_directories(output, dirs):
    os.mkdir(output); table = {}
    for d in dirs:
        for name in sorted(os.listdir(d)): table.setdefault(name, []).append(d)
    for name, ds in table.items(): union(os.path.join(output, name), [os.path.join(d, name) for d in ds])
if __name__ == "__main__":
    output, inputs = sys.argv[1], [os.path.abspath(i) for i in sys.argv[2:]]
    seen = list(dict.fromkeys(inputs))
    if os.path.exists(output): sys.exit("refusing to overwrite " + output)
    union_of_directories(output, seen); print("union-build:", output, "from", len(seen), "inputs")
PYEOF
python3 -c "import ast; ast.parse(open('$WORK/gcc-toolchain/union_build.py').read()); print('syntax OK')"
